"""Experiment result reporting utilities."""

import sys


def report_result(name, value):
    """Print a single experiment result in KEY: VALUE format."""
    print(f"{name}: {value}")
    sys.stdout.flush()


def run_experiments(experiments):
    """Run a list of (name, callable) experiment pairs."""
    for name, func in experiments:
        try:
            value = func()
            report_result(name, value)
        except Exception as e:
            report_result(name, f"ERROR: {e}")

"""CEGAR-style counterexample analysis, minimization and predicate refinement.

The module closes the loop around the Spacer verifier: a transition system is
verified against an *abstraction* of itself, and whenever the abstraction is
too coarse the counterexample it produces is analysed and used to sharpen the
abstraction.

Abstraction
    ``SystemAbstraction`` over-approximates a transition system in two ways.
    The transition relation is split into its top level conjuncts and only a
    subset of them -- initially none -- is kept; the dropped conjuncts are
    replaced by ``True``.  On top of that every predicate ``p`` currently held
    by the :class:`AbstractDomain` contributes the preservation constraint
    ``p(x) -> p(x')`` whenever that implication follows from the concrete
    transition relation.  Both ingredients are implied by the concrete
    relation, so the abstraction is sound: proving the abstraction safe proves
    the concrete system safe.

Refinement
    A counterexample of the abstraction is replayed against the *concrete*
    system by :class:`CEXValidator`.  If it survives, it is a real bug.  If it
    does not, :class:`PredicateRefiner` interpolates along the infeasible path
    to discover new predicates, and the loop restores the dropped conjunct the
    trace violated.  Since there are finitely many conjuncts and each spurious
    trace violates at least one dropped one, the loop always terminates: in the
    worst case the abstraction becomes the concrete system, which admits no
    spurious counterexample at all.

Interpolation
    This Z3 build exposes no interpolation API, so Craig interpolants are
    computed here from first principles.  For a split of an infeasible path
    into a prefix ``A`` and a suffix ``B``, the interpolant is the image of
    ``A`` on the shared step variables, obtained by eliminating the variables
    local to ``A`` with the ``qe`` tactic.  Every candidate is checked --
    ``A -> I`` valid and ``I and B`` unsatisfiable -- before it is accepted.

Calling convention
    ``init_cond(state)``, ``trans_rel(state, next_state)`` and
    ``safety(state)`` all take dictionaries mapping a program variable name to
    the z3 integer constant standing for it, and return a ``BoolRef``.
"""

import z3

__all__ = [
    "State",
    "Transition",
    "Counterexample",
    "ValidationResult",
    "CEXValidator",
    "AbstractDomain",
    "PredicateRefiner",
    "SystemAbstraction",
    "CEGARResult",
    "CEGARLoop",
    "collect_var_names",
    "build_trace",
]

#: Longest unrolling :func:`build_trace` will consider before giving up.
MAX_HORIZON = 96


# --------------------------------------------------------------------------
# Counterexample traces
# --------------------------------------------------------------------------


class State(object):
    """A concrete state: a mapping from variable name to integer value."""

    def __init__(self, values):
        self.values = dict(values)

    @property
    def variables(self):
        """The variable names of this state, in a stable order."""
        return sorted(self.values)

    def get(self, name, default=None):
        """Return the value of `name`, or `default` when it is not present."""
        return self.values.get(name, default)

    def __getitem__(self, name):
        return self.values[name]

    def __contains__(self, name):
        return name in self.values

    def __eq__(self, other):
        return isinstance(other, State) and self.values == other.values

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash(tuple(sorted(self.values.items())))

    def __repr__(self):
        body = ", ".join("%s=%s" % (name, self.values[name])
                         for name in self.variables)
        return "State(%s)" % body


class Transition(object):
    """A single step from `src` to `dst`, labelled with the `action` taken."""

    def __init__(self, src, dst, action="step"):
        self.src = src
        self.dst = dst
        self.action = action

    def is_stutter(self):
        """True when the step leaves every variable unchanged."""
        return self.src == self.dst

    def __repr__(self):
        return "Transition(%r -> %r, %s)" % (self.src, self.dst, self.action)


class Counterexample(object):
    """A finite execution trace, given as the list of its transitions."""

    def __init__(self, transitions):
        self.transitions = list(transitions)

    @property
    def length(self):
        """The number of transitions in the trace."""
        return len(self.transitions)

    @property
    def states(self):
        """Every state the trace visits, from the source of the first step."""
        if not self.transitions:
            return []
        return ([self.transitions[0].src]
                + [step.dst for step in self.transitions])

    def get_variable_trace(self, var_name):
        """Return the values `var_name` takes across all states of the trace."""
        return [state.get(var_name) for state in self.states]

    def __len__(self):
        return len(self.transitions)

    def __repr__(self):
        return "Counterexample(length=%d, %r)" % (self.length, self.states)


# --------------------------------------------------------------------------
# Small z3 helpers
# --------------------------------------------------------------------------


def _conjuncts(expr):
    """Split a (possibly nested) conjunction into its top level conjuncts."""
    if z3.is_and(expr):
        return [part for child in expr.children() for part in _conjuncts(child)]
    return [expr]


def _atoms(expr, found=None):
    """Collect the atomic boolean subterms of `expr` (comparisons, literals)."""
    found = [] if found is None else found
    if not z3.is_bool(expr):
        return found
    if z3.is_and(expr) or z3.is_or(expr) or z3.is_not(expr):
        for child in expr.children():
            _atoms(child, found)
    elif not (z3.is_true(expr) or z3.is_false(expr)):
        if not any(expr.eq(seen) for seen in found):
            found.append(expr)
    return found


def _is_trivial(expr):
    """True when `expr` simplifies to a constant and so carries no information."""
    try:
        simplified = z3.simplify(expr)
    except z3.Z3Exception:
        return True
    return z3.is_true(simplified) or z3.is_false(simplified)


def _valid(formula):
    """True when `formula` holds for every assignment."""
    solver = z3.Solver()
    solver.add(z3.Not(formula))
    return solver.check() == z3.unsat


def _satisfiable(*formulas):
    """True when the conjunction of `formulas` has a model."""
    solver = z3.Solver()
    solver.add(*formulas)
    return solver.check() == z3.sat


class _NameCollector(dict):
    """A variable environment that mints a fresh ``Int`` for every lookup.

    Passing one of these to a system's ``init``/``trans``/``safety`` callables
    records exactly which program variables they mention, so a caller does not
    have to spell the variable list out twice.
    """

    def __missing__(self, key):
        value = z3.Int(key)
        self[key] = value
        return value


def collect_var_names(init_cond, trans_rel, safety):
    """Return the sorted variable names mentioned by a transition system."""
    names = set()
    for build in (lambda: init_cond(_probe(names)),
                  lambda: trans_rel(_probe(names), _probe(names)),
                  lambda: safety(_probe(names))):
        try:
            build()
        except Exception:
            continue
    return sorted(names)


def _probe(sink):
    """Return a collector that records every name it is asked for in `sink`."""

    class _Sink(_NameCollector):
        def __missing__(self, key):
            sink.add(key)
            return _NameCollector.__missing__(self, key)

    return _Sink()


def _env(names, suffix=""):
    """Return ``{name: Int(name + suffix)}`` for every name in `names`."""
    return {name: z3.Int(name + suffix) for name in names}


def _bind(env, state):
    """Return the equalities pinning the variables of `env` to `state`."""
    return [env[name] == z3.IntVal(int(value))
            for name, value in state.values.items() if name in env]


def _read_state(model, env):
    """Read the values `model` assigns to the variables of `env`."""
    values = {}
    for name, const in env.items():
        value = model.eval(const, model_completion=True)
        values[name] = value.as_long() if hasattr(value, "as_long") else 0
    return State(values)


# --------------------------------------------------------------------------
# Validation
# --------------------------------------------------------------------------


class ValidationResult(object):
    """Outcome of replaying a counterexample against the concrete system.

    Attributes:
        is_real: True only when the initial state satisfies the initial
            condition, every step satisfies the transition relation and the
            final state violates the safety property.
        first_spurious_step: ``None`` when the trace is real, ``0`` when the
            initial state is not an initial state, the index ``i`` of the first
            infeasible transition, and ``len(transitions)`` when the trace does
            not actually end in a bad state.  `reason` disambiguates the two
            readings of ``0``.
        reason: Human readable explanation, ``None`` when the trace is real.
    """

    def __init__(self, is_real, first_spurious_step=None, reason=None):
        self.is_real = bool(is_real)
        self.first_spurious_step = first_spurious_step
        self.reason = reason

    def __repr__(self):
        if self.is_real:
            return "ValidationResult(real)"
        return "ValidationResult(spurious at %r: %s)" % (
            self.first_spurious_step, self.reason)


class CEXValidator(object):
    """Replay a counterexample step by step against a concrete system."""

    def __init__(self, var_names=None):
        self.var_names = list(var_names) if var_names else None

    def _names(self, cex):
        """The variables to reason about: the declared ones, or the trace's."""
        if self.var_names:
            return list(self.var_names)
        names = set()
        for state in cex.states:
            names.update(state.values)
        return sorted(names)

    def validate(self, cex, init_cond, trans_rel, safety):
        """Check whether `cex` is a real execution of the concrete system.

        Every check is a separate SMT query over the concrete values of the
        trace, so a failure pinpoints the exact step at which the trace stops
        being executable.

        Args:
            cex: The :class:`Counterexample` to replay.
            init_cond: ``init_cond(state_env)`` -> BoolRef.
            trans_rel: ``trans_rel(state_env, next_state_env)`` -> BoolRef.
            safety: ``safety(state_env)`` -> BoolRef.

        Returns:
            ValidationResult: see that class for the meaning of the fields.
        """
        states = cex.states
        if not states:
            return ValidationResult(False, 0, "the trace is empty")

        names = self._names(cex)
        current = _env(names)
        following = _env(names, "!next")

        if not _satisfiable(init_cond(current), *_bind(current, states[0])):
            return ValidationResult(
                False, 0, "the first state does not satisfy the initial condition")

        for index, step in enumerate(cex.transitions):
            if not _satisfiable(trans_rel(current, following),
                                *(_bind(current, step.src)
                                  + _bind(following, step.dst))):
                return ValidationResult(
                    False, index,
                    "transition %d is not allowed by the transition relation"
                    % index)

        if not _satisfiable(z3.Not(safety(current)), *_bind(current, states[-1])):
            return ValidationResult(
                False, len(cex.transitions),
                "the final state does not violate the safety property")

        return ValidationResult(True, None, None)


# --------------------------------------------------------------------------
# Predicate abstraction state
# --------------------------------------------------------------------------


class AbstractDomain(object):
    """The set of predicates currently tracked by the abstraction.

    The set is kept irredundant: a predicate that is already implied by one of
    the predicates present adds nothing and is rejected, and a predicate that
    implies an existing one makes that one redundant and replaces it.
    """

    def __init__(self, predicates=None):
        self.predicates = []
        for predicate in predicates or []:
            self.add_predicate(predicate)

    @property
    def predicate_count(self):
        """The number of predicates currently tracked."""
        return len(self.predicates)

    def abstract_state(self, concrete_state):
        """Evaluate every predicate on `concrete_state`.

        Args:
            concrete_state: A :class:`State` or a plain ``{name: value}`` dict.

        Returns:
            tuple: One boolean per predicate, in :attr:`predicates` order.  A
            predicate that does not evaluate to a constant -- because the state
            leaves one of its variables unassigned -- counts as ``False``.
        """
        values = (concrete_state.values if isinstance(concrete_state, State)
                  else dict(concrete_state))
        substitution = [(z3.Int(name), z3.IntVal(int(value)))
                        for name, value in values.items()]
        abstraction = []
        for predicate in self.predicates:
            try:
                evaluated = z3.simplify(z3.substitute(predicate, *substitution))
            except z3.Z3Exception:
                abstraction.append(False)
                continue
            abstraction.append(bool(z3.is_true(evaluated)))
        return tuple(abstraction)

    def is_subsumed(self, pred_new, pred_existing):
        """True when `pred_existing` implies `pred_new`, i.e. the new one adds nothing."""
        try:
            return _valid(z3.Implies(pred_existing, pred_new))
        except z3.Z3Exception:
            return False

    def add_predicate(self, pred):
        """Track `pred` unless an existing predicate already implies it.

        Any tracked predicate that `pred` implies becomes redundant and is
        dropped.

        Returns:
            bool: Whether the predicate was added.
        """
        if pred is None or not z3.is_bool(pred) or _is_trivial(pred):
            return False
        try:
            pred = z3.simplify(pred)
        except z3.Z3Exception:
            return False
        if any(pred.eq(known) for known in self.predicates):
            return False
        if any(self.is_subsumed(pred, known) for known in self.predicates):
            return False
        self.predicates = [known for known in self.predicates
                           if not self.is_subsumed(known, pred)]
        self.predicates.append(pred)
        return True

    def preservation_constraints(self, trans_rel, current, following):
        """Return the ``p(x) -> p(x')`` constraints entailed by `trans_rel`.

        Only the implications that genuinely follow from the concrete relation
        are returned, so conjoining them to an abstract transition relation
        keeps it an over-approximation.
        """
        constraints = []
        transition = trans_rel(current, following)
        for predicate in self.predicates:
            before = _rename(predicate, current)
            after = _rename(predicate, following)
            implication = z3.Implies(before, after)
            try:
                if _valid(z3.Implies(transition, implication)):
                    constraints.append(implication)
            except z3.Z3Exception:
                continue
        return constraints


def _rename(predicate, env):
    """Re-express `predicate`, written over plain names, in the `env` variables."""
    substitution = [(z3.Int(name), const) for name, const in env.items()]
    return z3.substitute(predicate, *substitution)


# --------------------------------------------------------------------------
# Refinement
# --------------------------------------------------------------------------


class PredicateRefiner(object):
    """Derive new predicates from an infeasible trace and shrink traces."""

    def __init__(self, domain=None, init_cond=None):
        self.domain = domain if domain is not None else AbstractDomain()
        self.init_cond = init_cond

    def extract_interpolants(self, cex, trans_rel, init_cond=None):
        """Compute Craig interpolants along the infeasible path of `cex`.

        The path is unrolled over one copy of the program variables per step.
        For every split point ``k`` the prefix

            ``A = init(x0) and trans(x0, x1) and ... and trans(x(k-1), xk)``

        is confronted with the suffix ``B``, which pins step ``k`` to the state
        the trace claims to be in.  Where ``A and B`` is unsatisfiable the two
        are separated by an interpolant: the image of ``A`` on the step ``k``
        variables, computed by eliminating the earlier steps with the ``qe``
        tactic.  Each candidate is verified (``A -> I`` valid and ``I and B``
        unsatisfiable) and then split into its atoms, which are the predicates
        the abstraction can use.

        Args:
            cex: The spurious :class:`Counterexample`.
            trans_rel: ``trans_rel(state_env, next_state_env)`` -> BoolRef.
            init_cond: Optional initial condition; defaults to the one the
                refiner was constructed with, and to ``True`` if there is none.

        Returns:
            list: The z3 predicates discovered, over plain variable names.
        """
        init_cond = init_cond if init_cond is not None else self.init_cond
        states = cex.states
        if len(states) < 2:
            return []

        names = sorted({name for state in states for name in state.values})
        steps = [_env(names, "@%d" % index) for index in range(len(states))]

        prefix = []
        if init_cond is not None:
            prefix.append(init_cond(steps[0]))
        prefix.extend(_bind(steps[0], states[0]))

        interpolants = []
        for split in range(1, len(states)):
            prefix = list(prefix) + [trans_rel(steps[split - 1], steps[split])]
            suffix = _bind(steps[split], states[split])
            if not suffix:
                continue
            formula_a = z3.And(*prefix) if prefix else z3.BoolVal(True)
            formula_b = z3.And(*suffix)
            if _satisfiable(formula_a, formula_b):
                continue  # the trace is still executable up to this step
            candidate = self._interpolate(formula_a, formula_b,
                                          [steps[i] for i in range(split)],
                                          steps[split], names)
            if candidate is None:
                continue
            for atom in _atoms(candidate):
                if not _is_trivial(atom) and not any(atom.eq(seen)
                                                     for seen in interpolants):
                    interpolants.append(atom)
        return interpolants

    def _interpolate(self, formula_a, formula_b, local_envs, shared_env, names):
        """Return an interpolant for the unsatisfiable ``formula_a and formula_b``.

        The interpolant is the projection of `formula_a` onto `shared_env`,
        obtained by existentially quantifying every variable local to the
        prefix and running quantifier elimination.  ``None`` is returned when
        the projection cannot be computed or fails its own validity check.
        """
        local = [const for env in local_envs for const in env.values()]
        try:
            goal = z3.Goal()
            goal.add(z3.Exists(local, formula_a) if local else formula_a)
            projected = z3.Tactic("qe")(goal).as_expr()
            projected = z3.simplify(projected)
        except z3.Z3Exception:
            return None
        if _is_trivial(projected):
            return None
        # A genuine interpolant implies nothing A does not, and still
        # contradicts B.
        if not _valid(z3.Implies(formula_a, projected)):
            return None
        if _satisfiable(projected, formula_b):
            return None
        return _plain(projected, shared_env, names)

    def strengthen_invariant(self, current_preds, new_interpolants):
        """Merge `new_interpolants` into `current_preds`, dropping redundancy.

        Returns:
            list: The merged predicate set; predicates implied by another
            member of the set are left out.
        """
        merged = AbstractDomain(current_preds)
        for predicate in new_interpolants:
            merged.add_predicate(predicate)
        return list(merged.predicates)

    def minimize_cex(self, cex, trans_rel):
        """Return the shortest trace reachable from `cex` by skipping steps.

        Three reductions are applied until none of them fires again:

        * a step that changes nothing is dropped;
        * a state that the trace visits twice makes the loop between the two
          visits redundant, so it is cut out;
        * whenever the transition relation permits a direct jump from state
          ``i`` to a later state ``j``, the steps in between are spliced out.

        Every reduction keeps the remaining steps executable, so the result is
        a valid trace with the same first and last state, never longer than the
        input.
        """
        states = cex.states
        if len(states) < 2:
            return Counterexample(list(cex.transitions))

        names = sorted({name for state in states for name in state.values})
        current = _env(names)
        following = _env(names, "!next")
        transition = trans_rel(current, following)

        def jumps(src, dst):
            return _satisfiable(transition,
                                *(_bind(current, src) + _bind(following, dst)))

        actions = [step.action for step in cex.transitions]
        changed = True
        while changed and len(states) > 1:
            changed = False
            # Drop stuttering steps.
            for index in range(len(states) - 1):
                if states[index] == states[index + 1]:
                    del states[index + 1]
                    del actions[index]
                    changed = True
                    break
            if changed:
                continue
            # Cut out loops: the trace returns to a state it already visited.
            for start in range(len(states)):
                repeat = next((other for other in range(len(states) - 1, start, -1)
                               if states[other] == states[start]), None)
                if repeat is not None:
                    del states[start + 1:repeat + 1]
                    del actions[start:repeat]
                    changed = True
                    break
            if changed:
                continue
            # Splice out the steps a single transition can jump over.
            for start in range(len(states) - 2):
                target = next((other for other in range(len(states) - 1, start + 1, -1)
                               if jumps(states[start], states[other])), None)
                if target is not None:
                    del states[start + 1:target]
                    del actions[start + 1:target]
                    changed = True
                    break

        transitions = [Transition(states[index], states[index + 1],
                                  actions[index] if index < len(actions) else "step")
                       for index in range(len(states) - 1)]
        return Counterexample(transitions)


def _plain(expr, env, names):
    """Rewrite `expr`, written over the variables of `env`, over plain names."""
    substitution = [(env[name], z3.Int(name)) for name in names if name in env]
    try:
        return z3.simplify(z3.substitute(expr, *substitution))
    except z3.Z3Exception:
        return expr


# --------------------------------------------------------------------------
# Abstraction of a transition system
# --------------------------------------------------------------------------


class SystemAbstraction(object):
    """A sound over-approximation of a concrete transition system.

    The transition relation is rebuilt from the conjuncts in :attr:`kept` --
    initially none, so the relation starts out as ``True`` -- conjoined with
    the preservation constraints the tracked predicates entail.  Both are
    implied by the concrete relation, so the abstraction only ever admits more
    behaviour than the real system.

    Attributes:
        conjuncts: The top level conjuncts of the concrete transition relation,
            each rendered as a callable ``(state, next_state) -> BoolRef``.
        kept: Indices of the conjuncts currently part of the abstraction.
        domain: The :class:`AbstractDomain` supplying the predicates.
    """

    def __init__(self, var_names, init_cond, trans_rel, safety, domain):
        self.var_names = list(var_names)
        self.init_cond = init_cond
        self.trans_rel = trans_rel
        self.safety = safety
        self.domain = domain
        self.kept = set()
        self.conjuncts = self._split_transition()

    def _split_transition(self):
        """Split the concrete transition relation into independent conjuncts."""
        current = _env(self.var_names, "!c")
        following = _env(self.var_names, "!n")
        parts = _conjuncts(self.trans_rel(current, following))
        conjuncts = []
        for part in parts:
            conjuncts.append(_Conjunct(part, current, following))
        return conjuncts

    @property
    def is_concrete(self):
        """True once every conjunct has been restored."""
        return len(self.kept) == len(self.conjuncts)

    def abstract_trans(self):
        """Return the abstract transition relation as a callable."""

        def trans(state, following):
            parts = [self.conjuncts[index].instantiate(state, following)
                     for index in sorted(self.kept)]
            parts.extend(self.domain.preservation_constraints(
                self.trans_rel, state, following))
            return z3.And(*parts) if parts else z3.BoolVal(True)

        return trans

    def restore_violated(self, src, dst):
        """Restore the first dropped conjunct that the step `src` -> `dst` breaks.

        Returns:
            int or None: The index restored, or ``None`` when the step already
            satisfies every dropped conjunct.
        """
        current = _env(self.var_names)
        following = _env(self.var_names, "!next")
        pinned = _bind(current, src) + _bind(following, dst)
        for index, conjunct in enumerate(self.conjuncts):
            if index in self.kept:
                continue
            if not _satisfiable(conjunct.instantiate(current, following), *pinned):
                self.kept.add(index)
                return index
        return None

    def restore_any(self):
        """Restore an arbitrary dropped conjunct, to guarantee progress."""
        for index in range(len(self.conjuncts)):
            if index not in self.kept:
                self.kept.add(index)
                return index
        return None


class _Conjunct(object):
    """One conjunct of a transition relation, re-instantiable in any variables."""

    def __init__(self, expr, current, following):
        self._expr = expr
        self._current = current
        self._following = following

    def instantiate(self, state, following):
        """Return this conjunct expressed over `state` and `following`."""
        substitution = []
        for name, const in self._current.items():
            if name in state:
                substitution.append((const, state[name]))
        for name, const in self._following.items():
            if name in following:
                substitution.append((const, following[name]))
        if not substitution:
            return self._expr
        return z3.substitute(self._expr, *substitution)

    def __repr__(self):
        return "_Conjunct(%s)" % self._expr


# --------------------------------------------------------------------------
# Bounded trace construction
# --------------------------------------------------------------------------


def build_trace(var_names, init_cond, trans_rel, safety, horizon,
                max_horizon=MAX_HORIZON, actions=None):
    """Find a trace that ends in a state violating `safety`, by unrolling.

    The system is unrolled to exactly `horizon` steps and the last state is
    required to be bad.  When no such path exists the horizon is doubled, up to
    `max_horizon`.  The witness returned is *some* path of that length, not
    necessarily the shortest one -- shortening it is the job of
    :meth:`PredicateRefiner.minimize_cex`.

    Args:
        var_names: The program variables.
        init_cond, trans_rel, safety: The system, in the usual convention.
        horizon: Unrolling depth to start from.
        max_horizon: Depth beyond which the search gives up.
        actions: Optional ``{label: predicate}`` mapping used to label each
            step; ``predicate(state, next_state)`` -> BoolRef.

    Returns:
        Counterexample or None: The witness, or ``None`` when no violating path
        of any considered length exists.
    """
    depth = max(1, int(horizon))
    while depth <= max_horizon:
        trace = _unroll(var_names, init_cond, trans_rel, safety, depth, actions)
        if trace is not None:
            return trace
        depth *= 2
    return None


def _unroll(var_names, init_cond, trans_rel, safety, depth, actions):
    """Solve one bounded model checking query of exactly `depth` steps."""
    steps = [_env(var_names, "@%d" % index) for index in range(depth + 1)]
    solver = z3.Solver()
    solver.add(init_cond(steps[0]))
    for index in range(depth):
        solver.add(trans_rel(steps[index], steps[index + 1]))
    solver.add(z3.Not(safety(steps[depth])))
    if solver.check() != z3.sat:
        return None

    model = solver.model()
    states = [_read_state(model, env) for env in steps]
    transitions = []
    for index in range(depth):
        label = _label_action(states[index], states[index + 1], var_names, actions)
        transitions.append(Transition(states[index], states[index + 1], label))
    return Counterexample(transitions)


def _label_action(src, dst, var_names, actions):
    """Name the action that explains the step `src` -> `dst`."""
    if src == dst:
        return "stutter"
    if not actions:
        return "step"
    current = _env(var_names)
    following = _env(var_names, "!next")
    pinned = _bind(current, src) + _bind(following, dst)
    for label, predicate in actions.items():
        if _satisfiable(predicate(current, following), *pinned):
            return label
    return "step"


# --------------------------------------------------------------------------
# The CEGAR loop
# --------------------------------------------------------------------------


class CEGARResult(object):
    """The verdict of a :class:`CEGARLoop` run.

    Attributes:
        safe: True when the system was proven safe.
        iterations: How many refinement rounds the loop needed.
        predicates: The predicates the abstraction ended up tracking.
        cex: The minimized real counterexample, or ``None``.
        original_cex: The counterexample before minimization, or ``None``.
        discovered: The predicates derived from interpolation, i.e. those the
            loop found rather than started with.
        exhausted: True when the loop stopped on its iteration or predicate
            budget instead of reaching a verdict.
        reason: A short explanation of the verdict.
    """

    def __init__(self, safe, iterations, predicates, cex=None,
                 original_cex=None, discovered=None, exhausted=False,
                 reason=None, name=None):
        self.safe = bool(safe)
        self.iterations = int(iterations)
        self.predicates = list(predicates)
        self.cex = cex
        self.original_cex = original_cex
        self.discovered = list(discovered or [])
        self.exhausted = bool(exhausted)
        self.reason = reason
        self.name = name

    @property
    def original_length(self):
        """Length of the counterexample before minimization."""
        return self.original_cex.length if self.original_cex else 0

    @property
    def minimized_length(self):
        """Length of the counterexample after minimization."""
        return self.cex.length if self.cex else 0

    def __repr__(self):
        verdict = "safe" if self.safe else ("exhausted" if self.exhausted
                                            else "unsafe")
        return "CEGARResult(%s, %s, iterations=%d, predicates=%d)" % (
            self.name or "system", verdict, self.iterations,
            len(self.predicates))


class CEGARLoop(object):
    """Counterexample-guided abstraction refinement for a transition system.

    Each round verifies the current abstraction with Spacer, replays any
    counterexample against the concrete system, and -- when the counterexample
    turns out to be spurious -- interpolates along the infeasible path and
    restores the transition conjunct the trace violated.
    """

    def __init__(self, init_cond, trans_rel, safety, max_iterations=20,
                 predicate_budget=50, var_names=None, name=None, horizon=6,
                 actions=None, seed_predicates=True):
        self.init_cond = init_cond
        self.trans_rel = trans_rel
        self.safety = safety
        self.max_iterations = int(max_iterations)
        self.predicate_budget = int(predicate_budget)
        self.name = name or "system"
        self.horizon = int(horizon)
        self.actions = actions
        self.var_names = (list(var_names) if var_names
                          else collect_var_names(init_cond, trans_rel, safety))

        self.domain = AbstractDomain()
        if seed_predicates:
            # The safety property is the obvious starting abstraction: when it
            # happens to be inductive the very first round already succeeds.
            for atom in _atoms(safety(_env(self.var_names))):
                self.domain.add_predicate(_plain(atom, _env(self.var_names),
                                                 self.var_names))
        self.seeded = list(self.domain.predicates)
        self.refiner = PredicateRefiner(self.domain, init_cond)
        self.validator = CEXValidator(self.var_names)
        self.abstraction = SystemAbstraction(self.var_names, init_cond,
                                             trans_rel, safety, self.domain)
        self.discovered = []

    def _verify_abstraction(self):
        """Ask Spacer whether the current abstraction is safe.

        The Horn encoding lives in :mod:`spacer_verifier`; the import is lazy
        so this module also works on its own, in which case an equivalent
        Fixedpoint is built here.
        """
        trans = self.abstraction.abstract_trans()
        sorts = [z3.IntSort()] * len(self.var_names)

        def as_list(callable_on_dict, arity=1):
            def wrapped(*vectors):
                envs = [dict(zip(self.var_names, vector)) for vector in vectors]
                return callable_on_dict(*envs)
            return wrapped

        try:
            from spacer_verifier import verify_transition_system
        except ImportError:
            return self._verify_inline(trans)
        outcome = verify_transition_system(
            self.name, sorts,
            as_list(self.init_cond), as_list(trans), as_list(self.safety))
        return outcome.get("safe", False), outcome.get("invariant")

    def _verify_inline(self, trans):
        """Fallback Horn encoding, used when :mod:`spacer_verifier` is absent."""
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        sorts = [z3.IntSort()] * len(self.var_names)
        inv = z3.Function("Inv", *(sorts + [z3.BoolSort()]))
        error = z3.Function("Error", z3.BoolSort())
        fp.register_relation(inv, error)
        current = _env(self.var_names)
        following = _env(self.var_names, "!next")
        order = [current[name] for name in self.var_names]
        order_next = [following[name] for name in self.var_names]
        fp.declare_var(*(order + order_next))
        fp.rule(inv(*order), [self.init_cond(current)])
        fp.rule(inv(*order_next), [inv(*order), trans(current, following)])
        fp.rule(error(), [inv(*order), z3.Not(self.safety(current))])
        try:
            answer = fp.query(error())
        except z3.Z3Exception:
            return False, None
        if answer == z3.unsat:
            try:
                return True, str(fp.get_answer())
            except z3.Z3Exception:
                return True, None
        return False, None

    def run(self):
        """Run the refinement loop to a verdict.

        Returns:
            CEGARResult: safe with the discovered predicates, unsafe with a
            minimized real counterexample, or exhausted when a budget ran out.
        """
        iterations = 0
        while iterations < self.max_iterations:
            iterations += 1

            safe, _invariant = self._verify_abstraction()
            if safe:
                return CEGARResult(True, iterations, self.domain.predicates,
                                   discovered=self.discovered, name=self.name,
                                   reason="the abstraction is inductively safe")

            cex = build_trace(self.var_names, self.init_cond,
                              self.abstraction.abstract_trans(), self.safety,
                              self.horizon, actions=self.actions)
            if cex is None:
                # Spacer disagrees with the bounded search: restore a conjunct
                # to sharpen the abstraction and try again.
                if self.abstraction.restore_any() is None:
                    return CEGARResult(False, iterations, self.domain.predicates,
                                       discovered=self.discovered, name=self.name,
                                       exhausted=True,
                                       reason="no counterexample trace could be built")
                continue

            verdict = self.validator.validate(cex, self.init_cond,
                                              self.trans_rel, self.safety)
            if verdict.is_real:
                minimized = self.refiner.minimize_cex(cex, self.trans_rel)
                return CEGARResult(False, iterations, self.domain.predicates,
                                   cex=minimized, original_cex=cex,
                                   discovered=self.discovered, name=self.name,
                                   reason="a real counterexample was found")

            self._refine(cex, verdict)
            if self.domain.predicate_count > self.predicate_budget:
                return CEGARResult(False, iterations, self.domain.predicates,
                                   discovered=self.discovered, name=self.name,
                                   exhausted=True,
                                   reason="the predicate budget was exhausted")

        return CEGARResult(False, iterations, self.domain.predicates,
                           discovered=self.discovered, name=self.name,
                           exhausted=True,
                           reason="the iteration budget was exhausted")

    def _refine(self, cex, verdict):
        """Sharpen the abstraction so that `cex` is no longer a trace of it."""
        for predicate in self.refiner.extract_interpolants(cex, self.trans_rel):
            if self.domain.add_predicate(predicate):
                self.discovered.append(predicate)

        step = verdict.first_spurious_step
        restored = None
        if step is not None and 0 <= step < len(cex.transitions):
            broken = cex.transitions[step]
            restored = self.abstraction.restore_violated(broken.src, broken.dst)
        if restored is None:
            restored = self.abstraction.restore_any()
        return restored

"""Experiments for the CEGAR counterexample minimizer.

Five transition systems with seeded bugs are handed to :class:`CEGARLoop`:
three of them are safe -- one immediately, two only after the abstraction has
been refined -- and two contain a genuine violation whose counterexample trace
is then minimized.

Every system is written in the dict-of-z3-constants convention used throughout
:mod:`verification.cex_minimizer`: ``init(state)``, ``trans(state, next)`` and
``safety(state)`` receive mappings from variable name to z3 integer constant.
"""

import z3

from framework import report_result
from verification.cex_minimizer import CEGARLoop


class CEGARSystem(object):
    """A transition system together with the budget its analysis needs."""

    def __init__(self, name, var_names, init, trans, safety, horizon,
                 actions=None, expected_safe=None):
        self.name = name
        self.var_names = list(var_names)
        self.init = init
        self.trans = trans
        self.safety = safety
        self.horizon = horizon
        self.actions = actions
        self.expected_safe = expected_safe

    def loop(self, **kwargs):
        """Build the :class:`CEGARLoop` that analyses this system."""
        return CEGARLoop(self.init, self.trans, self.safety,
                         var_names=self.var_names, name=self.name,
                         horizon=self.horizon, actions=self.actions, **kwargs)

    def __repr__(self):
        return "CEGARSystem(%s)" % self.name


# -- System 1: a counter whose assertion repeats the bound as a literal -----
# The loop runs while x < limit and limit never changes, so x never passes 10.
# The assertion spells the bound out again, which is the off-by-one trap: the
# safety atom on its own is not inductive, because nothing in it ties x to
# limit.  CEGAR has to restore the transition conjuncts to see that it holds.

def _counter_init(state):
    return z3.And(state["x"] == 0, state["limit"] == 10)


def _counter_trans(state, nxt):
    return z3.And(state["x"] < state["limit"],
                  nxt["x"] == state["x"] + 1,
                  nxt["limit"] == state["limit"])


def _counter_safety(state):
    return state["x"] <= 10


# -- System 2: two counters that grow without bound (genuinely unsafe) ------

def _double_init(state):
    return z3.And(state["x"] == 0, state["y"] == 0)


def _double_trans(state, nxt):
    return z3.And(nxt["x"] == state["x"] + 1, nxt["y"] == state["y"] + 2)


def _double_safety(state):
    return state["x"] + state["y"] < 50


# -- System 3: an array index walked over a buffer of the same length ------
# Safety needs three separate facts -- the index never goes below zero, never
# passes the element count, and the count equals the buffer size -- so the
# abstraction has to be refined several times before the proof goes through.

def _array_init(state):
    return z3.And(state["i"] == 0, state["n"] >= 0, state["size"] == state["n"])


def _array_trans(state, nxt):
    return z3.And(state["i"] < state["n"],
                  nxt["i"] == state["i"] + 1,
                  nxt["n"] == state["n"],
                  nxt["size"] == state["size"])


def _array_safety(state):
    return state["i"] <= state["size"]


# -- System 4: a loop whose invariant is exactly its safety property --------
# x >= 0 is preserved by x := x + 1, so the seeded abstraction proves it on
# the very first iteration, with no refinement at all.

def _loop_init(state):
    return state["x"] == 0


def _loop_trans(state, nxt):
    return nxt["x"] == state["x"] + 1


def _loop_safety(state):
    return state["x"] >= 0


# -- System 5: a bounded buffer that overflows -----------------------------
# The producer may push one or two items at a time and either side may idle,
# so a bounded unrolling finds a padded trace that minimization can compress.

def _pc_produce_one(state, nxt):
    return z3.And(nxt["items"] == state["items"] + 1,
                  nxt["produced"] == state["produced"] + 1,
                  nxt["consumed"] == state["consumed"])


def _pc_produce_two(state, nxt):
    return z3.And(nxt["items"] == state["items"] + 2,
                  nxt["produced"] == state["produced"] + 2,
                  nxt["consumed"] == state["consumed"])


def _pc_consume(state, nxt):
    return z3.And(state["items"] > 0,
                  nxt["items"] == state["items"] - 1,
                  nxt["consumed"] == state["consumed"] + 1,
                  nxt["produced"] == state["produced"])


def _pc_idle(state, nxt):
    return z3.And(nxt["items"] == state["items"],
                  nxt["produced"] == state["produced"],
                  nxt["consumed"] == state["consumed"])


PRODUCER_CONSUMER_ACTIONS = {
    "produce1": _pc_produce_one,
    "produce2": _pc_produce_two,
    "consume": _pc_consume,
    "idle": _pc_idle,
}


def _pc_init(state):
    return z3.And(state["items"] == 0, state["produced"] == 0,
                  state["consumed"] == 0)


def _pc_trans(state, nxt):
    return z3.Or(*[action(state, nxt)
                   for action in PRODUCER_CONSUMER_ACTIONS.values()])


def _pc_safety(state):
    return state["items"] <= 3


#: The five systems the experiment analyses.
SYSTEMS = [
    CEGARSystem("counter_offbyone", ["x", "limit"], _counter_init,
                _counter_trans, _counter_safety, horizon=6, expected_safe=True),
    CEGARSystem("double_counter", ["x", "y"], _double_init, _double_trans,
                _double_safety, horizon=20, expected_safe=False),
    CEGARSystem("array_bounds", ["i", "n", "size"], _array_init, _array_trans,
                _array_safety, horizon=6, expected_safe=True),
    CEGARSystem("simple_loop", ["x"], _loop_init, _loop_trans, _loop_safety,
                horizon=4, expected_safe=True),
    CEGARSystem("producer_consumer", ["items", "produced", "consumed"],
                _pc_init, _pc_trans, _pc_safety, horizon=8,
                actions=PRODUCER_CONSUMER_ACTIONS, expected_safe=False),
]


def analyze_all():
    """Run the CEGAR loop on every system and return the results in order."""
    return [system.loop().run() for system in SYSTEMS]


def run_cegar_experiments():
    """Analyse the five systems and report the CEGAR metrics.

    Returns:
        dict: The reported values, so tests can reuse them.
    """
    results = analyze_all()
    unsafe = [result for result in results if result.cex is not None]

    values = {
        "CEGAR_ITERATIONS": sum(result.iterations for result in results),
        "CEGAR_PREDICATES_ADDED": sum(len(result.predicates) for result in results),
        "CEGAR_CEX_LENGTH_ORIGINAL": sum(result.original_length for result in unsafe),
        "CEGAR_CEX_LENGTH_MINIMIZED": sum(result.minimized_length for result in unsafe),
        "CEGAR_VERIFIED_SAFE": sum(1 for result in results if result.safe),
    }
    for key in ("CEGAR_ITERATIONS", "CEGAR_PREDICATES_ADDED",
                "CEGAR_CEX_LENGTH_ORIGINAL", "CEGAR_CEX_LENGTH_MINIMIZED",
                "CEGAR_VERIFIED_SAFE"):
        report_result(key, values[key])
    return values


if __name__ == "__main__":
    run_cegar_experiments()

