def minimize_cex(self, cex, trans_rel):
    """Return the shortest trace reachable from `cex` by skipping steps.

    Three reductions are applied until none of them fires again:

    * a step that changes nothing is dropped;
    * a state that the trace visits twice makes the loop between the two
      visits redundant, so it is cut out;
    * whenever the transition relation permits a direct jump from state
      ``i`` to a later state ``j``, the steps in between are spliced out.

    Every reduction keeps the remaining steps executable, so the result is
    a valid trace with the same first and last state, never longer than the
    input.
    """
    states = cex.states
    if len(states) < 2:
        return Counterexample(list(cex.transitions))

    names = sorted({name for state in states for name in state.values})
    current = _env(names)
    following = _env(names, "!next")
    transition = trans_rel(current, following)

    def jumps(src, dst):
        return _satisfiable(transition,
                            *(_bind(current, src) + _bind(following, dst)))

    actions = [step.action for step in cex.transitions]
    changed = True
    while changed and len(states) > 1:
        changed = False
        # Drop stuttering steps.
        for index in range(len(states) - 1):
            if states[index] == states[index + 1]:
                del states[index + 1]
                del actions[index]
                changed = True
                break
        if changed:
            continue
        # Cut out loops: the trace returns to a state it already visited.
        for start in range(len(states)):
            repeat = next((other for other in range(len(states) - 1, start, -1)
                           if states[other] == states[start]), None)
            if repeat is not None:
                del states[start + 1:repeat + 1]
                del actions[start:repeat]
                changed = True
                break
        if changed:
            continue
        # Splice out the steps a single transition can jump over.
        for start in range(len(states) - 2):
            target = next((other for other in range(len(states) - 1, start + 1, -1)
                           if jumps(states[start], states[other])), None)
            if target is not None:
                del states[start + 1:target]
                del actions[start + 1:target]
                changed = True
                break

    transitions = [Transition(states[index], states[index + 1],
                              actions[index] if index < len(actions) else "step")
                   for index in range(len(states) - 1)]
    return Counterexample(transitions)

