def minimize_cex(self, cex, trans_rel, safety=None, init_cond=None):
    """Return the shortest trace reachable from `cex` by dropping steps.

    Five reductions are applied, the first two once and the rest until none
    of them fires again:

    * the trace is cut at the *first* state that violates safety -- what
      makes a counterexample a counterexample is that it reaches a bad
      state, so every step after the first one is dead weight;
    * symmetrically, if a later state is also an initial state the trace may
      simply start there;
    * a step that changes nothing is dropped;
    * a state the trace visits twice makes the loop between the two visits
      redundant, so it is cut out;
    * whenever the transition relation permits a direct jump from state
      ``i`` to a later state ``j``, the steps in between are spliced out.

    Every reduction keeps the remaining steps executable, keeps the first
    state initial and the last state bad, and never lengthens the trace, so
    the result is a valid counterexample of the same system.

    Args:
        cex: The trace to shrink.
        trans_rel: ``trans_rel(state_env, next_state_env)`` -> BoolRef.
        safety: Optional safety property, needed for the truncation step;
            defaults to the one the refiner was constructed with.  Without
            it the trace keeps its final state.
        init_cond: Optional initial condition, likewise needed only for the
            prefix step.

    Returns:
        Counterexample: The shrunk trace, never longer than `cex`.
    """
    safety = safety if safety is not None else self.safety
    init_cond = init_cond if init_cond is not None else self.init_cond
    states = cex.states
    if len(states) < 2:
        return Counterexample(list(cex.transitions))

    names = sorted({name for state in states for name in state.values})
    probe = _env(names)
    current = _env(names)
    following = _env(names, "!next")
    transition = trans_rel(current, following)

    def jumps(src, dst):
        return _satisfiable(transition,
                            *(_bind(current, src) + _bind(following, dst)))

    actions = [step.action for step in cex.transitions]

    # Cut everything after the first violation of the safety property.
    if safety is not None:
        violated = z3.Not(safety(probe))
        for index in range(1, len(states)):
            if _satisfiable(violated, *_bind(probe, states[index])):
                del states[index + 1:]
                del actions[index:]
                break

    # Start from the last state that is still an initial state.
    if init_cond is not None and len(states) > 2:
        entry = init_cond(probe)
        start = 0
        for index in range(len(states) - 1):
            if _satisfiable(entry, *_bind(probe, states[index])):
                start = index
        if start:
            del states[:start]
            del actions[:start]

    changed = True
    while changed and len(states) > 2:
        changed = False
        # Drop stuttering steps.
        for index in range(len(states) - 1):
            if states[index] == states[index + 1]:
                del states[index + 1]
                del actions[index]
                changed = True
                break
        if changed:
            continue
        # Cut out loops: the trace returns to a state it already visited.
        for start in range(len(states)):
            repeat = next((other for other in range(len(states) - 1, start, -1)
                           if states[other] == states[start]), None)
            if repeat is not None:
                del states[start + 1:repeat + 1]
                del actions[start:repeat]
                changed = True
                break
        if changed:
            continue
        # Splice out the steps a single transition can jump over.
        for start in range(len(states) - 2):
            target = next((other for other in range(len(states) - 1, start + 1, -1)
                           if jumps(states[start], states[other])), None)
            if target is not None:
                del states[start + 1:target]
                del actions[start + 1:target]
                changed = True
                break

    transitions = [Transition(states[index], states[index + 1],
                              actions[index] if index < len(actions) else "step")
                   for index in range(len(states) - 1)]
    return Counterexample(transitions)
